INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/04-dang-ky-hkd-va-mst.md#270', 'KB/04-dang-ky-hkd-va-mst.md', '4.22. Chồng cho thuê xe ô tô độc lập với HKD của vợ: có phải đăng ký HKD riêng', NULL, 'CASE_EVIDENCE', '04 — Đăng ký HKD & mã số thuế
