INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/05-so-sach-chung-tu.md#325', 'KB/05-so-sach-chung-tu.md', '5.26. Quy trình tự làm sổ sách của HKD trên 1 tỷ: bảng kê 02/TNDN, sổ S2a-HKD, hóa đơn tổng trong ngày, tờ khai cuối quý', NULL, 'CASE_EVIDENCE', '05 — Sổ sách & chứng từ
## 5.26. Quy trình tự làm sổ sách của HKD trên 1 tỷ: bảng kê 02/TNDN, sổ S2a-HKD, hóa đơn tổng trong ngày, tờ khai cuối quý
