INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#646', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Kinh nghiệm] Đã xử lý xong cảnh báo hệ số K bằng cách tích hợp lại phần mềm HĐĐT sang MST CCCD', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
## [Kinh nghiệm] Đã xử lý xong cảnh báo hệ số K bằng cách tích hợp lại phần mềm HĐĐT sang MST CCCD
- Ngày đăng: 05/08/2026
- Tóm tắt: Chủ hộ đã giải quyết được vấn đề bị cảnh báo hệ số K sau khi tham khảo ý kiến của nhóm: liên hệ bên phần mềm xuất hóa đơn điện tử để tích hợp lại từ MST cũ 001 sang MST CCCD thì không còn bị cảnh báo nữa. Đăng lại cho cả nhà tham khảo nếu ai gặp trường hợp tương tự.
- Link: https://facebook.com/groups/251248059536000/permalink/1738396364154488/
- Ghi chú: kinh nghiệm cá nhân thực tế; 91 lượt tương tác, 45 bình luận.');
INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#647', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Kinh nghiệm] Khuyên kiểm tra eTax định kỳ để phát hiện bị mạo danh đăng ký kinh doanh', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
## [Kinh nghiệm] Khuyên kiểm tra eTax định kỳ để phát hiện bị mạo danh đăng ký kinh doanh
- Ngày đăng: 04/08/2026
- Tóm tắt: Chia sẻ từng có trường hợp đối tượng xấu dùng ảnh CCCD/CMND của người khác để đăng ký thành lập doanh nghiệp trái phép, đến khi phát hiện thì người bị mạo danh mới biết mình đứng tên doanh nghiệp. Từ 01/7/2026 quy trình đăng ký đã siết chặt (xác nhận qua VNeID). Khuyên mọi người định kỳ kiểm tra trên eTax Mobile bằng số CCCD/MST để kịp thời phát hiện doanh nghiệp hoặc HKD bị đăng ký trái phép bằng thông tin của mình hoặc phát sinh nợ thuế. Kèm hướng dẫn các bước xử lý khi bị mạo danh: làm việc với Phòng Đăng ký kinh doanh, trình báo công an.
- Link: https://facebook.com/groups/251248059536000/permalink/1737343474259777/
- Ghi chú: kinh nghiệm cá nhân.');
INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#648', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Kinh nghiệm] Mẹo chọn đúng tờ khai 01/CNKD theo từng thời kỳ', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
