INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#676', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Tồn đọng] Hộ trên 1 tỷ tự làm: bảng kê 02/TNDN, sổ S2A, hóa đơn tổng ngày, nộp tờ khai qua eTax — chưa rõ đã đủ chưa', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
