INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#677', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Tồn đọng] Xin đóng mã số thuế, trạng thái đã đóng nhưng chưa hoàn thành thủ tục, hơn 1 tháng chưa có phản hồi', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
