INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#705', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Tồn đọng] Muốn sửa tờ khai bổ sung từ giảm trừ 500tr lên 1 tỷ nhưng hệ thống mặc định 500 không sửa được', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
