INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#734', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Kinh nghiệm] Nhận 2 tờ khai (1 chấp nhận, 1 không chấp nhận) là bình thường', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
## [Kinh nghiệm] Nhận 2 tờ khai (1 chấp nhận, 1 không chấp nhận) là bình thường
- Ngày đăng: 27/07/2026
- Tóm tắt: Chủ hộ chia sẻ kinh nghiệm sau đợt thông báo doanh thu 6 tháng đầu năm: nhận về 2 tờ khai, 1 tờ chấp nhận và 1 tờ không chấp nhận là bình thường. Tờ khai thường được chấp nhận trong 24-48 giờ làm việc tùy hệ thống có quá tải hay không. Bài viết cũng nhận hỗ trợ các hộ còn lỗi tờ khai chưa khai được (313 lượt thích, 361 bình luận).
- Link: https://facebook.com/groups/1504215237164872/permalink/2095130364740020/
- Ghi chú: ý kiến cá nhân.');
INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#735', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Kinh nghiệm] Cảnh báo số điện thoại mạo danh cán bộ thuế', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
## [Kinh nghiệm] Cảnh báo số điện thoại mạo danh cán bộ thuế
- Ngày đăng: 07/09/2026
- Tóm tắt: Chủ hộ chia sẻ từng bị số điện thoại lạ gọi đến yêu cầu kê khai trên thuế, lúc đầu tưởng thật. Trước đó hộ này đã ngừng hoạt động và bị phạt tiền chậm thuế gần 10 triệu. Sau khi gọi lên số điện thoại thuế khu vực để kiểm tra mới biết là mạo danh. Cảnh báo mọi người cẩn thận với số điện thoại tự xưng nhân viên thuế cơ sở.
- Link: https://facebook.com/groups/1504215237164872/permalink/2132850184301371/
- Ghi chú: ý kiến cá nhân.');
INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#736', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Kinh nghiệm] Mẹo nộp nhiều tờ khai chậm trong cùng 1 ngày để mức phạt thấp nhất', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
