INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#752', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Tồn đọng] Muốn đóng MST cho thuê phòng, đã có thông báo nghĩa vụ thuế nhưng nộp HS chấm dứt trên DVC không được', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
