INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#971', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Tồn đọng] Nộp thuế bị đòi mã smart OTP nhưng không nhận được mã', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
