INSERT OR REPLACE INTO rag_chunks (id, file, section, ref_id, tier, text) VALUES ('KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md#993', 'KB/11-ton-dong-va-kinh-nghiem-ca-nhan.md', '[Tồn đọng] eTax Mobile không có lựa chọn HKD doanh thu dưới 500 triệu để kê khai đơn giản', NULL, 'CASE_EVIDENCE', 'Tồn đọng thực tế & kinh nghiệm xử lý cá nhân (thông tin phụ tham khảo)
